#!/usr/bin/env python3
"""商品发布命令 — CLI 入口"""

from __future__ import annotations

COMMAND_NAME = "product_publish"
COMMAND_DESC = "图片发布商品（单图/批量，支持本地图片或图片链接）"

import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', '..'))

import argparse
import io
import json
import platform
import subprocess
import tempfile
